package io.forgeloop.runner;
import java.net.URI; import java.net.http.*; import java.nio.charset.StandardCharsets;
/** Minimal GraphQL transport; never writes tokens or source content to stdout. */
public final class RunnerClient { private final HttpClient http; private final URI endpoint; public RunnerClient(HttpClient http,URI controlPlane){this.http=http;this.endpoint=controlPlane.resolve("/graphql");} public String register(RunnerConfig config) throws Exception {String query="mutation($input:RegisterRunnerInput!){registerRunner(input:$input){id}}";String variables="{\"input\":{\"token\":\""+escape(config.registrationToken())+"\",\"name\":\""+escape(config.name())+"\",\"version\":\""+escape(config.version())+"\",\"capabilities\":["+config.capabilities().stream().map(value->"\""+escape(value)+"\"").reduce((a,b)->a+","+b).orElse("")+"]}}";return post(query,variables);} public String heartbeat(String runnerId) throws Exception{return post("mutation($runnerId:ID!){runnerHeartbeat(runnerId:$runnerId){id lastHeartbeatAt}}","{\"runnerId\":\""+escape(runnerId)+"\"}");} private String post(String query,String variables)throws Exception{String body="{\"query\":\""+escape(query)+"\",\"variables\":"+variables+"}";HttpResponse<String> response=http.send(HttpRequest.newBuilder(endpoint).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body,StandardCharsets.UTF_8)).build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200||response.body().contains("\"errors\""))throw new IllegalStateException("Control-plane request failed");return response.body();} private static String escape(String value){return value.replace("\\","\\\\").replace("\"","\\\"");}}
